      de: ["Gesamtfläche der Terminals: 279 Hektar.", "Anzahl der Liegeplätze: 24.", "Jährlicher Umschlag: über 20 Millionen TEU.", "Eröffnung des ersten Terminals: 1976.", "Maximale Krantragfähigkeit: 50 Tonnen.", "Wassertiefe an den Liegeplätzen: bis zu 15,5 Meter."],
