    imageHint: "Hong Kong International Airport aerial view of terminal buildings",
    descriptionAdvanced: {
      de: "Der Hongkong International Airport (HKG) auf der Insel Chek Lap Kok ist einer der verkehrsreichsten Frachtflughäfen der Welt. Er wurde 1998 eröffnet und ersetzte den alten Flughafen Kai Tak. Der Flughafen verfügt über zwei Start- und Landebahnen und eine dritte ist im Bau, um die Kapazität auf 100 Millionen Passagiere pro Jahr zu erhöhen. Er ist ein wichtiges Drehkreuz für den Luftverkehr in Asien, mit Verbindungen zu über 220 Zielen. Der Frachtverkehr ist besonders bedeutend; jährlich werden über 4 Millionen Tonnen Fracht umgeschlagen. Der Flughafen ist bekannt für seine Effizienz und wurde mehrfach als bester Flughafen der Welt ausgezeichnet. Die Flughafenbehörde investiert kontinuierlich in moderne Technologien und Infrastruktur.",
      hu: "A Hongkongi nemzetközi repülőtér a modern mérnöki tudomány egyik legimpozánsabb alkotása, amely szinte teljes egészében mesterséges területen fekszik. A Chek Lap Kok és Lam Chau szigetek körüli tengerfeltöltéssel létrehozott platformon 1998-ban nyílt meg a légikötő, felváltva a legendás Kai Tak repülőteret. A repülőtér a világ egyik legfontosabb áruszállító központja, évek óta vezeti a globális légi teherforgalmi listákat. A Sir Norman Foster által tervezett 1-es terminál letisztult formáival és hatalmas üvegfelületeivel ma is modern hatást kelt. A létesítmény nemcsak utazási csomópont, hanem egy valóságos aerotropolis, saját vasúti összeköttetéssel, bevásárlóközpontokkal és szállodákkal. A folyamatban lévő fejlesztések biztosítják, hogy Hongkong továbbra is Ázsia egyik legfontosabb légiközlekedési kapuja maradjon.",
      ro: "Aeroportul Internațional Hong Kong este o capodoperă a ingineriei contemporane, fiind construit pe o platformă gigantică de teren recuperat din mare, care a unit insulele Chek Lap Kok și Lam Chau. Deschis în 1998 pentru a înlocui vechiul aeroport Kai Tak, acesta a devenit rapid unul dintre cele mai importante noduri de transport aerian din Asia și cel mai mare terminal de marfă din lume. Terminalul 1, proiectat de celebrul arhitect Norman Foster, este renumit pentru designul său aerodinamic și eficiența fluxurilor de pasageri. Aeroportul este conectat direct la centrul orașului printr-un tren de mare viteză, oferind o tranziție rapidă pentru călători. Extinderea continuă, inclusiv construcția celei de-a treia piste, reflectă rolul strategic al acestui hub în economia globală. Cu facilități de lux și o logistică impecabilă, aeroportul este o componentă vitală a identității moderne a Hong Kong-ului.",
      en: "Hong Kong International Airport (HKIA) is a marvel of modern infrastructure, primarily built on a massive artificial island created by reclaiming land around Chek Lap Kok and Lam Chau. Since its opening in 1998, it has served as a critical gateway to Asia, replacing the historically challenging Kai Tak Airport. HKIA is consistently ranked as the world's busiest cargo hub, playing a vital role in global logistics and supply chains. The airport's Terminal 1, designed by Foster + Partners, features a distinctive vaulted roof that optimizes natural light and passenger flow. Beyond its aviation functions, the airport features high-speed rail links to the city center and extensive retail complexes, making it a self-contained commercial hub. The ongoing expansion into a three-runway system underscores its strategic importance for the future of the Pearl River Delta region.",
      es: "El Aeropuerto Internacional de Hong Kong (HKG), situado en la isla de Chek Lap Kok, es uno de los aeropuertos de carga más transitados del mundo. Se inauguró en 1998, sustituyendo al antiguo aeropuerto de Kai Tak. El aeropuerto cuenta con dos pistas y una tercera está en construcción para aumentar la capacidad a 100 millones de pasajeros al año. Es un centro neurálgico para el tráfico aéreo en Asia, con conexiones a más de 220 destinos. El tráfico de carga es especialmente significativo, con más de 4 millones de toneladas gestionadas anualmente. El aeropuerto es conocido por su eficiencia y ha sido galardonado varias veces como el mejor del mundo. La autoridad aeroportuaria invierte continuamente en tecnologías e infraestructuras modernas.",
      pt: "O Aeroporto Internacional de Hong Kong (HKG), na ilha de Chek Lap Kok, é um dos aeroportos de carga mais movimentados do mundo. Abriu em 1998, substituindo o antigo aeroporto de Kai Tak. O aeroporto tem duas pistas e uma terceira está em construção para aumentar a capacidade para 100 milhões de passageiros por ano. É um centro importante para o tráfego aéreo na Ásia, com ligações a mais de 220 destinos. O tráfego de carga é particularmente significativo; anualmente são movimentadas mais de 4 milhões de toneladas de carga. O aeroporto é conhecido pela sua eficiência e foi eleito várias vezes o melhor do mundo. A autoridade aeroportuária investe continuamente em tecnologias e infraestruturas modernas.",
      fr: "L'aéroport international de Hong Kong (HKG), situé sur l'île de Chek Lap Kok, est l'un des aéroports de fret les plus fréquentés au monde. Il a ouvert en 1998, remplaçant l'ancien aéroport de Kai Tak. L'aéroport dispose de deux pistes et une troisième est en construction pour porter la capacité à 100 millions de passagers par an. C'est une plaque tournante majeure pour le trafic aérien en Asie, avec des liaisons vers plus de 220 destinations. Le trafic de fret est particulièrement important, avec plus de 4 millions de tonnes traitées annuellement. L'aéroport est réputé pour son efficacité et a été élu plusieurs fois meilleur aéroport au monde. L'autorité aéroportuaire investit continuellement dans des technologies et des infrastructures modernes.",
    },
