      de: ["Eröffnungsdatum: 6. Juli 1998.", "Anzahl der Start- und Landebahnen: 2, plus eine im Bau (Fertigstellung 2030).", "Jährliche Passagierkapazität: über 70 Millionen (nach Fertigstellung der dritten Bahn: 100 Millionen).", "Jährliches Frachtaufkommen: über 4 Millionen Tonnen.", "Anzahl der Flugziele: über 220.", "Fläche des Flughafengeländes: 1.255 Hektar."],
