      hu: "Hongkong legmagasabb épülete, amely jelentős pénzügyi központként szolgál Nyugat-Kowloonban. Neves befektetési bankoknak és egy luxusszállodának ad otthont.",
      ro: "Cea mai înaltă clădire din Hong Kong servește ca un centru financiar major în West Kowloon. Găzduiește bănci de investiții renumite și un hotel de lux.",
