    imageHint: "International Commerce Centre skyscraper in West Kowloon",
    descriptionAdvanced: {
      de: "Das International Commerce Centre (ICC) ist mit einer Höhe von 484 Metern das markanteste Merkmal der Skyline von West Kowloon und das höchste Gebäude Hongkongs. Dieser 108-stöckige Wolkenkratzer wurde 2010 fertiggestellt und bildet den Kern der Union Square Entwicklung. Er beherbergt einige der weltweit bedeutendsten Finanzinstitutionen und Investmentbanken, was seine Rolle als globaler Wirtschaftsknotenpunkt unterstreicht. In den obersten Stockwerken befindet sich das Ritz-Carlton, eines der höchstgelegenen Hotels der Welt, von dem aus man einen atemberaubenden Blick über den Victoria Harbour genießt. Für Besucher bietet die Sky100-Aussichtsplattform im 100. Stock ein spektakuläres 360-Grad-Panorama der Stadt. Das Gebäude ist nicht nur ein architektonisches Meisterwerk der Ingenieurskunst, sondern auch durch seine direkte Anbindung an den Flughafen-Express und das Hochgeschwindigkeitsbahnnetz ein logistisches Zentrum der Extraklasse, das Hongkong mit dem Rest der Welt verbindet.",
      hu: "Az International Commerce Centre (ICC) 484 méteres magasságával Hongkong legmagasabb épülete és Nyugat-Kowloon látképének meghatározó eleme. A 2010-ben átadott, 108 emeletes felhőkarcoló az Union Square fejlesztési projekt központi eleme, amely a modern építészet és a globális pénzügyi világ összefonódását jelképezi. Az épületben kapott helyet számos neves nemzetközi befektetési bank és pénzügyi szolgáltató központja, míg a legfelső szinteken a világ egyik legmagasabb szállodája, a Ritz-Carlton üzemel. A turisták számára a 100. emeleten található Sky100 kilátó kínál páratlan, 360 fokos panorámát a Victoria-kikötőre és a környező szigetekre. Az ICC kiváló közlekedési csomópont is egyben, hiszen közvetlen összeköttetésben áll a repülőtéri gyorsvasúttal és a nagysebességű vasútállomással, így a város és a világ egyik legforgalmasabb és technológiailag legfejlettebb üzleti központjaként funkcionál.",
      ro: "International Commerce Centre (ICC) este cea mai înaltă clădire din Hong Kong, dominând orizontul districtului West Kowloon cu o înălțime de 484 de metri. Finalizat în 2010, acest zgârie-nori cu 108 etaje reprezintă inima dezvoltării Union Square și un simbol al puterii economice a orașului. Clădirea găzduiește sediile unor bănci de investiții de talie mondială, oferind spații de birouri ultra-moderne integrate într-un design structural remarcabil. La etajele superioare se află prestigiosul hotel Ritz-Carlton, oferind oaspeților experiența unică de a fi cazați într-unul dintre cele mai înalte hoteluri din lume. Pentru publicul larg, platforma de observație Sky100, situată la etajul 100, oferă vederi panoramice spectaculoase de 360 de grade asupra Portului Victoria și a întregii metropole. Designul său sustenabil și integrarea perfectă cu rețelele de transport rapid fac din ICC un model de urbanism vertical și un punct de reper tehnologic esențial pentru Asia de Est.",
      en: "Standing at 484 meters tall, the International Commerce Centre (ICC) is the iconic centerpiece of the West Kowloon skyline and the tallest building in Hong Kong. Completed in 2010 as part of the Union Square development, this 108-story skyscraper is a premier global financial hub, housing the regional headquarters of major international investment banks. The building's upper floors are home to the luxurious Ritz-Carlton Hong Kong, famously known as one of the highest hotels in the world, featuring an infinity pool and bar with unparalleled views. Tourists flock to the Sky100 observation deck on the 100th floor for a stunning 360-degree panorama of Victoria Harbour and the city's dense urban landscape. Engineered with cutting-edge environmental technology, the ICC is seamlessly integrated with the Airport Express and high-speed rail links, making it a critical node in Hong Kong's transportation network and a testament to modern vertical engineering.",
      es: "El International Commerce Centre (ICC) en West Kowloon es, con 484 metros de altura, el edificio más alto de Hong Kong. Se completó en 2010 y alberga oficinas, un hotel y una plataforma de observación. El rascacielos forma parte del proyecto Union Square y está conectado directamente con la estación MTR de West Kowloon. El ICC ofrece un total de 260.000 metros cuadrados de superficie útil en sus 118 plantas. En las plantas superiores se encuentra el hotel Ritz-Carlton, uno de los más altos del mundo. El edificio es un símbolo de la fuerza económica de Hong Kong y alberga numerosas empresas multinacionales. La plataforma de observación Sky100 ofrece una vista panorámica de la ciudad y el puerto.",
      pt: "O International Commerce Centre (ICC) em West Kowloon é, com 484 metros de altura, o edifício mais alto de Hong Kong. Foi concluído em 2010 e alberga escritórios, um hotel e uma plataforma de observação. O arranha-céus faz parte do projeto Union Square e está ligado diretamente à estação MTR West Kowloon. O ICC oferece um total de 260.000 metros quadrados de área útil em 118 andares. Nos andares superiores encontra-se o hotel Ritz-Carlton, que é um dos hotéis mais altos do mundo. O edifício é um símbolo da força económica de Hong Kong e acolhe inúmeras empresas multinacionais. A plataforma de observação Sky100 oferece uma vista panorâmica sobre a cidade e o porto.",
      fr: "L'International Commerce Centre (ICC) à West Kowloon est, avec ses 484 mètres de haut, le plus haut bâtiment de Hong Kong. Achevé en 2010, il abrite des bureaux, un hôtel et une plateforme d'observation. Le gratte-ciel fait partie du projet Union Square et est directement relié à la station MTR West Kowloon. L'ICC offre un total de 260 000 mètres carrés de surface utile sur 118 étages. Les étages supérieurs accueillent l'hôtel Ritz-Carlton, l'un des plus hauts hôtels au monde. Le bâtiment est un symbole de la puissance économique de Hong Kong et abrite de nombreuses entreprises multinationales. La plateforme d'observation Sky100 offre une vue panoramique sur la ville et le port.",
    },
