    description: {
      de: "Ein ikonischer Wolkenkratzer in Central, der den Hauptsitz der Hong Kong Monetary Authority beherbergt. Er ist ein Symbol für Hongkongs Status als Finanzzentrum.",
      hu: "Ikonikus felhőkarcoló Central negyedben, amely a Hongkongi Monetáris Hatóság székhelye. Hongkong pénzügyi központ státuszának szimbóluma.",
      ro: "Un zgârie-nori iconic în Central, care găzduiește sediul Autorității Monetare din Hong Kong. Este un simbol al statutului orașului de centru financiar.",
      en: "An iconic skyscraper in Central housing the headquarters of the Hong Kong Monetary Authority. It is a symbol of Hong Kong's status as a financial hub.",
      es: "Un rascacielos icónico en Central que alberga la sede de la Autoridad Monetaria de Hong Kong. Es un símbolo del estatus de Hong Kong como centro financiero.",
      pt: "Um arranha-céu icónico em Central que alberga a sede da Autoridade Monetária de Hong Kong. É um símbolo do estatuto de Hong Kong como centro financeiro.",
      fr: "Un gratte-ciel emblématique de Central abritant le siège de l'Autorité monétaire de Hong Kong. Il symbolise le statut de Hong Kong en tant que centre financier.",
    },
    facts: {
      de: ["Zweithöchstes Gebäude der Stadt", "Entworfen von Cesar Pelli", "Sitz der HK Monetary Authority", "415 Meter Gesamthöhe"],
      hu: ["A város második legmagasabb épülete", "Cesar Pelli tervezte", "A Hongkongi Monetáris Hatóság székhelye", "415 méteres teljes magasság"],
      ro: ["A doua cea mai înaltă clădire din oraș", "Proiectat de Cesar Pelli", "Sediul Autorității Monetare HK", "415 metri înălțime totală"],
      en: ["Second tallest building in the city", "Designed by Cesar Pelli", "Headquarters of HK Monetary Authority", "415 meters total height"],
      es: ["Segundo edificio más alto de la ciudad", "Diseñado por Cesar Pelli", "Sede de la HK Monetary Authority", "415 metros de altura total"],
      pt: ["Segundo edifício mais alto da cidade", "Projetado por Cesar Pelli", "Sede da HK Monetary Authority", "415 metros de altura total"],
      fr: ["Deuxième plus haut bâtiment de la ville", "Conçu par Cesar Pelli", "Siège de la HK Monetary Authority", "Hauteur totale de 415 mètres"],
    },
    imageHint: "Two International Finance Centre tower at the harbor front",
    descriptionAdvanced: {
      de: "Das Two International Finance Centre (2IFC) in Central Hongkong ist mit 415 Metern Höhe das zweithöchste Gebäude der Stadt. Es wurde 2003 eröffnet und beherbergt Finanzinstitute, Anwaltskanzleien und andere Unternehmen. Der Wolkenkratzer ist ein herausragendes Beispiel moderner Architektur und ein Symbol für Hongkongs Rolle als globales Finanzzentrum. Das Gebäude hat 88 Stockwerke und bietet rund 185.000 Quadratmeter Bürofläche. Es ist Teil des International Finance Centre Komplexes, der auch das Four Seasons Hotel und das Einkaufszentrum ifc mall umfasst. Die Fassade aus Glas und Stahl verleiht dem Gebäude ein elegantes Erscheinungsbild. Der 2IFC ist berühmt für seine nachhaltigen Designs und energieeffizienten Systeme.",
      hu: "A Two International Finance Centre (2IFC) Hongkong sziluettjének egyik legmeghatározóbb eleme, amely Central negyed szívében tornyosodik a Victoria kikötő fölé. A Cesar Pelli által tervezett, 415 méter magas felhőkarcoló 2003-as átadásakor a város legmagasabb épülete volt, és ma is a világ egyik legfontosabb pénzügyi központjának szimbóluma. Az épület ad otthont a Hongkongi Monetáris Hatóságnak, amely a város központi bankjaként funkcionál. Különleges, fokozatosan keskenyedő formája és a tetején található „korona” messziről felismerhetővé teszi. A 88 emeletes torony nemcsak irodáknak ad helyet, hanem az IFC Mall bevásárlóközponttal is össze van kötve, amely közvetlen kapcsolatot biztosít a repülőtéri gyorsvasúthoz, így Hongkong globális elérhetőségének és gazdasági erejének egyik legfontosabb csomópontja a nemzetközi üzleti életben.",
      ro: "Two International Finance Centre (2IFC) este unul dintre cele mai emblematice repere ale orizontului din Hong Kong, dominând cartierul Central de la o înălțime de 415 metri. Proiectat de renumitul arhitect Cesar Pelli și finalizat în 2003, zgârie-norul cu 88 de etaje simbolizează puterea economică a regiunii și statutul său de centru financiar global. Clădirea găzduiește sediul Autorității Monetare din Hong Kong (HKMA), instituția responsabilă de stabilitatea monedei locale. Designul său elegant, care se îngustează spre vârf pentru a culmina cu o structură distinctivă în formă de coroană, este optimizat pentru a rezista taifunurilor frecvente din zonă. Integrat direct cu terminalul feroviar care face legătura cu aeroportul, 2IFC nu este doar un spațiu de birouri de lux, ci și un nod vital de transport și un simbol al eficienței și modernității asiatice.",
      en: "Standing at 415 meters, Two International Finance Centre (2IFC) is a defining landmark of Hong Kong's skyline, soaring above Victoria Harbour in the Central District. Designed by the acclaimed architect Cesar Pelli and completed in 2003, the 88-story skyscraper served as the city's tallest building for several years and remains a potent symbol of its status as a premier global financial hub. The tower houses the headquarters of the Hong Kong Monetary Authority, reflecting its vital role in the regional economy. Its sleek, tapering design is crowned by a distinctive top that is brilliantly illuminated at night, making it visible from across the territory. Beyond its corporate role, the building is seamlessly integrated with the IFC Mall and the Airport Express station, representing the pinnacle of urban connectivity and architectural achievement in a dense business district.",
      es: "El Two International Finance Centre (2IFC) en Central, Hong Kong, es, con 415 metros de altura, el segundo edificio más alto de la ciudad. Se inauguró en 2003 y alberga instituciones financieras, bufetes de abogados y otras empresas. El rascacielos es un ejemplo sobresaliente de arquitectura moderna y un símbolo del papel de Hong Kong como centro financiero global. El edificio tiene 88 plantas y ofrece unos 185.000 metros cuadrados de espacio de oficinas. Forma parte del complejo International Finance Centre, que también incluye el Four Seasons Hotel y el centro comercial ifc mall. Su fachada de vidrio y acero le otorga una apariencia elegante. El 2IFC es famoso por su diseño sostenible y sistemas energéticamente eficientes.",
      pt: "O Two International Finance Centre (2IFC) em Central, Hong Kong, é, com 415 metros de altura, o segundo edifício mais alto da cidade. Foi inaugurado em 2003 e alberga instituições financeiras, escritórios de advogados e outras empresas. O arranha-céu é um exemplo notável de arquitetura moderna e um símbolo do papel de Hong Kong como centro financeiro global. O edifício tem 88 andares e oferece cerca de 185.000 metros quadrados de área de escritórios. Faz parte do complexo International Finance Centre, que também inclui o Four Seasons Hotel e o centro comercial ifc mall. A fachada de vidro e aço confere ao edifício uma aparência elegante. O 2IFC é famoso pelos seus designs sustentáveis e sistemas energeticamente eficientes.",
      fr: "Le Two International Finance Centre (2IFC), situé à Central, Hong Kong, est le deuxième plus haut bâtiment de la ville avec ses 415 mètres. Ouvert en 2003, il accueille des institutions financières, des cabinets d'avocats et d'autres entreprises. Le gratte-ciel est un exemple remarquable d'architecture moderne et un symbole du rôle de Hong Kong en tant que centre financier mondial. Le bâtiment compte 88 étages et offre environ 185 000 mètres carrés de bureaux. Il fait partie du complexe International Finance Centre, qui comprend également l'hôtel Four Seasons et le centre commercial ifc mall. Sa façade en verre et en acier lui confère une allure élégante. Le 2IFC est réputé pour sa conception durable et ses systèmes économes en énergie.",
    },
