      pt: ["Área: 24 hectares.", "Ano de inauguração: 2004.", "Número de empresas residentes: mais de 1.500.", "Número de pessoas empregadas: cerca de 10.000.", "Número de programas de incubação: 3.", "Investimento total no desenvolvimento: 1,6 mil milhões de euros."],
