    imageHint: "Bank of China Tower unique triangular glass architecture",
    descriptionAdvanced: {
      de: "Der Bank of China Tower (BOC Tower) in Central Hongkong wurde 1990 fertiggestellt und ist 367 Meter hoch. Das von IM Pei entworfene Gebäude ist ein ikonisches Wahrzeichen der Stadt. Die markante Fassade aus Glas und Stahl besteht aus Dreiecksformen, die Stabilität symbolisieren. Der Turm hat 72 Stockwerke und bietet Büroflächen für die Bank of China und andere Mieter. Das Gebäude ist bekannt für seine innovative Struktur und war eines der ersten Hochhäuser mit einem vollständig aus Stahlrahmen bestehenden Kern. Der BOC Tower ist ein Symbol für die wirtschaftliche Öffnung Chinas in den 1990er Jahren. Er ist eines der bekanntesten Gebäude Hongkongs und wird oft in Filmen und Medien dargestellt.",
      hu: "A Bank of China Tower Hongkong egyik legikonikusabb felhőkarcolója, amely a Central negyed szívében magasodik. Az 1990-ben átadott épületet a Pritzker-díjas építész, I. M. Pei tervezte, és megjelenése azonnal forradalmasította a város látképét. A 315 méter magas (az antennákkal együtt 367 méteres) torony szerkezete a növő bambuszszárat szimbolizálja, amely a kínai kultúrában a vitalitás és a jólét jelképe. Az épület különlegessége a prizmatikus üveghomlokzat, amely visszatükrözi a város fényeit és a környező hegyeket. Építésekor ez volt Ázsia legmagasabb épülete, és az első, amely Kínán kívül ilyen mértékben reprezentálta a modern kínai gazdasági erőt. A belső terekben a funkcionalitás és a modernitás találkozik, miközben a szerkezet merevsége lehetővé teszi, hogy a torony ellenálljon a régióra jellemző tájfunoknak is.",
      ro: "Turnul Bank of China este unul dintre cei mai emblematici zgârie-nori din Hong Kong, dominând orizontul districtului financiar Central. Finalizată în 1990 după planurile celebrului arhitect I. M. Pei, structura a devenit imediat un simbol al modernității și al puterii economice chineze. Cu o înălțime de 315 metri până la acoperiș, designul său futurist este inspirat de creșterea tulpinii de bambus, simbolizând vitalitatea și progresul în cultura locală. Fațada sa prismatică, compusă din panouri de sticlă triunghiulare, reflectă lumina orașului într-un mod spectaculos, oferind clădirii un aspect mereu schimbător. Deși la momentul construcției a generat controverse legate de principiile Feng Shui din cauza colțurilor sale ascuțite, astăzi este considerată o capodoperă a ingineriei structurale, capabilă să reziste celor mai puternice taifunuri care lovesc periodic metropola.",
      en: "The Bank of China Tower is a defining landmark of Hong Kong’s skyline, situated in the heart of the Central district. Completed in 1990 and designed by the renowned architect I. M. Pei, the building is celebrated for its distinctive triangular glass curtain walls. Its structural form is inspired by the growth of bamboo, symbolizing vitality and prosperity in Chinese culture. Standing 315 meters tall, it was the tallest building in Asia at the time of its completion. The tower’s innovative framework not only creates a striking aesthetic but also provides exceptional stability against the region's frequent typhoons. Despite initial debates regarding its sharp angles and Feng Shui, it has become one of the most photographed and recognized structures in the world. Visitors often admire its shimmering facade from the nearby Victoria Harbour, especially during the 'Symphony of Lights' show.",
      es: "La Torre del Banco de China (BOC Tower) en Central Hong Kong se completó en 1990 y tiene 367 metros de altura. El edificio, diseñado por I. M. Pei, es un hito icónico de la ciudad. Su fachada de vidrio y acero consta de formas triangulares que simbolizan la estabilidad. La torre tiene 72 pisos y ofrece oficinas para el Banco de China y otros inquilinos. El edificio es conocido por su estructura innovadora y fue uno de los primeros rascacielos con un núcleo compuesto totalmente por un marco de acero. La BOC Tower es un símbolo de la apertura económica de China en la década de 1990 y aparece frecuentemente en películas y medios.",
      pt: "A Torre do Banco da China (BOC Tower) em Central Hong Kong foi concluída em 1990 e tem 367 metros de altura. O edifício, projetado por I. M. Pei, é um marco icónico da cidade. A fachada de vidro e aço é composta por formas triangulares que simbolizam estabilidade. A torre tem 72 andares e oferece escritórios para o Banco da China e outros inquilinos. O edifício é conhecido pela sua estrutura inovadora e foi um dos primeiros arranha-céus com um núcleo constituído inteiramente por uma estrutura de aço. A BOC Tower é um símbolo da abertura económica da China na década de 1990 e é frequentemente representada em filmes e meios de comunicação.",
      fr: "La tour de la Bank of China (BOC Tower) à Central Hong Kong a été achevée en 1990 et culmine à 367 mètres. Conçu par I. M. Pei, le bâtiment est un monument emblématique de la ville. La façade distinctive en verre et en acier est composée de formes triangulaires symbolisant la stabilité. La tour compte 72 étages et propose des bureaux pour la Bank of China et d'autres locataires. Le bâtiment est connu pour sa structure innovante et a été l'un des premiers gratte-ciel dotés d'un noyau entièrement constitué d'une structure en acier. La BOC Tower est un symbole de l'ouverture économique de la Chine dans les années 1990 et est souvent représentée dans les films et les médias.",
    },
