    imageHint: "HSBC Main Building Hong Kong high-tech architecture",
    descriptionAdvanced: {
      de: "Das HSBC Main Building in Hongkong ist ein Meilenstein der modernen Architektur und wurde vom britischen Architekten Norman Foster entworfen. Bei seiner Fertigstellung im Jahr 1985 war es das teuerste Bürogebäude der Welt. Die Konstruktion folgt den Prinzipien der High-Tech-Architektur: Es gibt keinen zentralen Betonkern, stattdessen wird die Struktur von fünf äußeren Stahlmodulen getragen, was maximale Flexibilität im Innenraum ermöglicht. Ein weiteres markantes Merkmal ist der Einsatz von natürlichem Licht, das über ein System von Spiegeln (Sonnenspiegeln) tief in das Atrium geleitet wird. Bei der Planung wurde streng auf Feng-Shui-Prinzipien geachtet, um Wohlstand und Harmonie zu sichern. Dies zeigt sich unter anderem in der freien Sicht auf den Victoria Harbour und den zwei berühmten bronzenen Löwenstatuen, Stephen und Stitt, die den Eingang bewachen. Das Gebäude gilt als Symbol für Hongkongs Status als globales Finanzzentrum und beeindruckt durch seine futuristische Ästhetik in der Skyline von Central.",
      hu: "A hongkongi HSBC főépület a modern építészet egyik legikonikusabb alkotása, amelyet a világhírű brit építész, Norman Foster tervezett. Az 1985-ben átadott felhőkarcoló korának legdrágább irodaépülete volt, és a high-tech építészeti stílus úttörőjének számít. Különlegessége, hogy nincs központi tartószerkezete; a súlyt külső acélmodulok hordozzák, ami lehetővé tette a belső terek teljesen szabad alakítását. Az épület tervezésekor kiemelt figyelmet fordítottak a fengsuj elveire: az alaprajz és az elhelyezkedés a pozitív energiák áramlását szolgálja, a bejáratnál pedig két híres bronzoroszlán, Stephen és Stitt 'őrzi' a bank vagyonát. Az épület belsejében egy hatalmas átrium található, ahová egy speciális tükörrendszer irányítja be a természetes napfényt. A HSBC székház nem csupán egy pénzügyi központ, hanem Hongkong gazdasági erejének és innovatív szellemiségének egyik legfontosabb vizuális szimbóluma a Victoria kikötő partján.",
      ro: "Clădirea principală HSBC din Hong Kong este o operă monumentală a arhitecturii high-tech, proiectată de celebrul arhitect britanic Norman Foster. Finalizată în 1985, structura a revoluționat designul zgârie-norilor prin absența unui nucleu central de susținere, greutatea fiind preluată de module externe din oțel suspendate. Această soluție inginerească inovatoare permite o flexibilitate totală a spațiilor interioare. Clădirea încorporează principii fundamentale de Feng Shui pentru a asigura prosperitatea, având o vedere neobstrucționată către port și fiind păzită la intrare de doi lei celebri din bronz, numiți Stephen și Stitt. Un sistem ingenios de oglinzi motorizate urmărește soarele și direcționează lumina naturală prin atriumul central până la nivelul străzii. Situată la adresa 1 Queen's Road Central, clădirea rămâne un simbol al puterii financiare a Hong Kong-ului și un exemplu de design sustenabil avant-la-lettre, fiind construită din componente prefabricate transportate din întreaga lume și asamblate la fața locului.",
      en: "The HSBC Main Building in Hong Kong is a masterpiece of high-tech architecture designed by the renowned British architect Norman Foster. Completed in 1985, it was at the time the most expensive office building in the world. Its radical design features a visible steel exoskeleton, eliminating the need for a central supporting core and allowing for vast, open-plan interior spaces. The building is famous for its strict adherence to Feng Shui principles, which dictated its orientation toward Victoria Harbour and the placement of the iconic bronze lions, Stephen and Stitt, at the entrance. A notable feature is the 'sunscoop' system, which uses giant mirrors to reflect natural sunlight deep into the central atrium. Constructed from prefabricated modules manufactured globally, the building reflects Hong Kong's identity as a cutting-edge global financial hub. It stands as a testament to structural expressionism and remains one of the most recognizable and critically acclaimed structures in the city's spectacular skyline.",
      es: "El edificio principal de HSBC en el centro de Hong Kong es una obra maestra arquitectónica terminada en 1985. El edificio tiene 179 metros de altura y 44 pisos. Diseñado por Norman Foster, destaca por su diseño modular y vigas de acero visibles. Es famoso por su construcción innovadora, donde los pisos están suspendidos de una estructura de soporte externa. Alberga la sede de HSBC, uno de los bancos más grandes del mundo. El vestíbulo de entrada mide 52 metros de altura y se utiliza para eventos públicos. El edificio simboliza el papel de Hong Kong como centro financiero global y atrae a muchos visitantes cada año.",
      pt: "O edifício principal do HSBC no centro de Hong Kong é uma obra-prima arquitetónica concluída em 1985. O edifício tem 179 metros de altura e 44 andares. Foi projetado por Norman Foster e caracteriza-se por um design modular e vigas de aço visíveis. O edifício é famoso pela sua construção inovadora, na qual os andares estão suspensos numa estrutura de suporte exterior. Alberga a sede do HSBC, um dos maiores bancos do mundo. O átrio de entrada tem 52 metros de altura e oferece espaço para eventos públicos. O edifício é um símbolo do papel de Hong Kong como centro financeiro global e atrai muitos visitantes todos os anos.",
      fr: "Le bâtiment principal de la HSBC à Central Hong Kong est un chef-d'œuvre architectural achevé en 1985. L'édifice mesure 179 mètres de haut et compte 44 étages. Conçu par Norman Foster, il se distingue par un design modulaire et des poutres en acier apparentes. Le bâtiment est célèbre pour sa construction innovante, où les étages sont suspendus à une structure de support externe. Il abrite le siège de la HSBC, l'une des plus grandes banques au monde. Le hall d'entrée mesure 52 mètres de haut et peut accueillir des événements publics. Le bâtiment est un symbole du rôle de Hong Kong en tant que centre financier mondial et attire chaque année de nombreux visiteurs.",
    },
