      hu: "Épületkomplexum Central negyedben, amely a Hongkongi Tőzsde kereskedési helyszínének ad otthont. A régió részvénykereskedelmének operatív központja.",
      ro: "Un complex de clădiri în Central care găzduiește bursa de valori din Hong Kong. Este centrul operațional al tranzacționării de acțiuni în regiune.",
