      ro: ["Sediul HKEX", "Trei turnuri interconectate", "Centrul serviciilor financiare", "Colecție extinsă de artă"],
      en: ["Home to the HKEX", "Three interconnected towers", "Financial services hub", "Extensive art collection"],
      es: ["Sede de HKEX", "Tres torres conectadas", "Centro de servicios financieros", "Extensa colección de arte"],
