    imageHint: "Exchange Square towers in Hong Kong Central",
    descriptionAdvanced: {
      de: "Der Exchange Square im Herzen des Stadtteils Central ist das architektonische Symbol für Hongkongs Status als globales Finanzzentrum. Der vom Architekturbüro P&T entworfene Komplex beherbergt den Handelssaal der Hongkonger Börse (HKEX) und besteht aus drei markanten Türmen, die durch ihre Fassaden aus rosafarbenem Granit und silbernem Glas bestechen. Die in den 1980er Jahren errichteten Gebäude One, Two und Three Exchange Square sind durch ein hochmodernes System von Fußgängerbrücken miteinander und mit anderen wichtigen Gebäuden in Central verbunden. Ein besonderes Merkmal ist der öffentlich zugängliche Platz, der eine hochkarätige Sammlung moderner Kunstwerke beherbergt, darunter die berühmte Skulptur \"Oval with Points\" von Henry Moore. Als operativer Knotenpunkt der Finanzdienstleistungen zieht der Komplex täglich Tausende von Geschäftsleuten an und bleibt einer der begehrtesten Bürostandorte in der gesamten asiatisch-pazifischen Region.",
      hu: "Az Exchange Square Hongkong Central negyedének egyik legfontosabb épületegyüttese, amely a Hongkongi Tőzsde (HKEX) központjaként a régió pénzügyi világának dobogó szíve. A P&T Architects által tervezett, az 1980-as évek közepén átadott komplexum három toronyból áll (One, Two és Three Exchange Square), amelyeket modern üveg- és gránitfelületek jellemeznek. Az épületek nemcsak funkcionális irodaterek, hanem építészeti jelképek is, amelyek rose-gránit burkolatukkal tűnnek ki a vízparti látképből. Az épületek lábánál található köztér figyelemre méltó képzőművészeti gyűjteménnyel rendelkezik; itt látható többek között Henry Moore híres bronzszobra, az \"Oval with Points\". A komplexum stratégiai csomópont a város magasvasúti és gyalogoshíd-hálózatában, közvetlen összeköttetést biztosítva a fontosabb üzleti központok, luxus bevásárlóközpontok és a központi kompkikötő között.",
      ro: "Exchange Square este un complex de birouri de prestigiu situat în districtul Central din Hong Kong, fiind sediul oficial al Bursei de Valori din Hong Kong (HKEX). Proiectat de biroul de arhitectură P&T și finalizat în etape în anii 1980, complexul este format din trei turnuri interconectate, recunoscute după fațadele lor elegante din granit roz și sticlă reflectorizantă argintie. Dincolo de rolul său crucial în finanțele globale, Exchange Square este faimos pentru piața sa publică ce găzduiește o colecție impresionantă de sculpturi moderne, piesa centrală fiind opera lui Henry Moore, \"Oval with Points\". Complexul servește ca un punct vital de conexiune în sistemul de pasarele suspendate al orașului, facilitând accesul rapid către terminalele de feribot, marile bănci și centrele comerciale de lux. Este un loc unde arhitectura de top întâlnește fluxul constant al capitalului internațional, definind pulsul economic al metropolei.",
      en: "Exchange Square is a premier office complex located in the Central district of Hong Kong, serving as the physical home of the Hong Kong Stock Exchange (HKEX). Designed by the renowned P&T Architects and completed in the mid-1980s, the complex consists of three interconnected towers: One, Two, and Three Exchange Square. The architecture is characterized by its elegant use of rose-colored granite and silver reflective glass, making it a standout feature of the waterfront skyline. Beyond its financial importance, the plaza at the base of the towers is famous for its extensive collection of contemporary art, including Henry Moore’s bronze sculpture \"Oval with Points\" and works by Dame Elisabeth Frink. The complex is an essential node in the city's elevated walkway system, seamlessly connecting major corporate headquarters, high-end shopping malls, and the Central Ferry Piers, facilitating the movement of thousands of professionals daily.",
      es: "Exchange Square, en el centro de Hong Kong, es un destacado complejo de negocios compuesto por dos torres y una plaza. Inaugurado en 1985, alberga la Bolsa de Hong Kong (HKEX). Las dos torres miden 188 y 169 metros de altura. Exchange Square es un lugar central para el comercio de acciones en Asia, con volúmenes diarios de miles de millones de dólares. La plaza cuenta con obras de arte y una fuente. El complejo está conectado directamente con la estación de MTR Hong Kong y el International Finance Centre. Exchange Square desempeña un papel clave en la infraestructura financiera de Hong Kong y simboliza el mercado global de capitales.",
      pt: "A Exchange Square, no centro de Hong Kong, é um importante complexo empresarial composto por duas torres e uma praça. Inaugurado em 1985, alberga a Bolsa de Valores de Hong Kong (HKEX). As duas torres têm 188 metros e 169 metros de altura. A Exchange Square é um local central para a negociação de ações na Ásia, com um volume diário de negociação de vários mil milhões de dólares. A praça está decorada com obras de arte e uma fonte. O complexo está diretamente ligado à estação de MTR Hong Kong Station e ao International Finance Centre. A Exchange Square desempenha um papel fundamental na infraestrutura financeira de Hong Kong e é um símbolo do mercado global de capitais.",
      fr: "Exchange Square, situé au centre de Hong Kong, est un complexe d'affaires majeur composé de deux tours et d'une place. Ouvert en 1985, il abrite la Bourse de Hong Kong (HKEX). Les deux tours mesurent respectivement 188 mètres et 169 mètres de haut. Exchange Square est un lieu central pour le commerce d'actions en Asie, avec un volume de transactions quotidien de plusieurs milliards de dollars. La place est agrémentée d'œuvres d'art et d'une fontaine. Le complexe est directement relié à la station MTR Hong Kong et à l'International Finance Centre. Exchange Square joue un rôle clé dans l'infrastructure financière de Hong Kong et symbolise le marché mondial des capitaux.",
    },
