      ro: ["Suprafață totală: 96.000 de metri pătrați.", "Anul deschiderii: 1997.", "Număr de hale expoziționale: 5.", "Capacitate auditoriu: 1.800 de locuri.", "Înălțimea cupolei de sticlă: 30 de metri.", "Vizitatori anuali: peste 3 milioane."],
      en: ["Total area: 96,000 square meters.", "Year opened: 1997.", "Number of exhibition halls: 5.", "Auditorium capacity: 1,800 seats.", "Height of glass dome: 30 meters.", "Annual visitors: over 3 million."],
      es: ["Superficie total: 96.000 metros cuadrados.", "Año de inauguración: 1997.", "Número de salas de exposición: 5.", "Capacidad del auditorio: 1.800 asientos.", "Altura de la cúpula de cristal: 30 metros.", "Visitantes anuales: más de 3 millones."],
      pt: ["Área total: 96.000 metros quadrados.", "Ano de inauguração: 1997.", "Número de pavilhões de exposição: 5.", "Capacidade do auditório: 1.800 lugares.", "Altura da cúpula de vidro: 30 metros.", "Visitantes anuais: mais de 3 milhões."],
      fr: ["Surface totale : 96 000 mètres carrés.", "Année d'ouverture : 1997.", "Nombre de halls d'exposition : 5.", "Capacité de l'auditorium : 1 800 places.", "Hauteur du dôme de verre : 30 mètres.", "Visiteurs annuels : plus de 3 millions."],
