      es: ["Más de 60 hectáreas de superficie", "Sectores como farmacia y logística", "Proximidad a la frontera con Shenzhen", "Gestionado por HKSTP"],
      pt: ["Mais de 60 hectares de área", "Setores como farmácia e logística", "Proximidade com a fronteira de Shenzhen", "Gerido pela HKSTP"],
