      pt: ["Área: 77 hectares.", "Ano de abertura: 1991.", "Número de empresas: cerca de 120.", "Proximidade a Tseung Kwan O New Town (população: 400.000).", "Estação MTR: Tseung Kwan O (linha Tseung Kwan O).", "Distância média ao aeroporto: 30 quilómetros."],
      fr: ["Superficie : 77 hectares.", "Année d'ouverture : 1991.", "Nombre d'entreprises : environ 120.", "Proximité de Tseung Kwan O New Town (population : 400 000).", "Station MTR : Tseung Kwan O (ligne Tseung Kwan O).", "Distance moyenne de l'aéroport : 30 kilomètres."],
