      pt: ["Altura do One Island East: 308 metros.", "Número de torres de escritórios no Taikoo Place: 5.", "Área do Taikoo Place: 44.000 metros quadrados.", "Abertura do Cityplaza: 1983.", "Estação de MTR Quarry Bay: linhas Island e Tseung Kwan O.", "Número de empregados em Quarry Bay: mais de 50.000."],
      fr: ["Hauteur du One Island East : 308 mètres.", "Nombre de tours de bureaux à Taikoo Place : 5.", "Surface de Taikoo Place : 44 000 mètres carrés.", "Ouverture de Cityplaza : 1983.", "Station de MTR Quarry Bay : lignes Island et Tseung Kwan O.", "Nombre d'employés à Quarry Bay : plus de 50 000."],
