      en: ["District area: about 10 square kilometers.", "Population: over 600,000 residents.", "Length of Kwun Tong Promenade: 1.5 kilometers.", "Number of converted factory buildings: over 50.", "MTR line: Kwun Tong Line.", "Largest shopping mall: apm (35,000 square meters)."],
      es: ["Superficie del distrito: unos 10 kilómetros cuadrados.", "Población: más de 600.000 habitantes.", "Longitud del paseo de Kwun Tong: 1,5 kilómetros.", "Número de edificios de fábricas convertidos: más de 50.", "Línea de MTR: Kwun Tong Line.", "Centro comercial más grande: apm (35.000 metros cuadrados)."],
      pt: ["Área do distrito: cerca de 10 quilómetros quadrados.", "População: mais de 600.000 habitantes.", "Comprimento da Kwun Tong Promenade: 1,5 quilómetros.", "Número de edifícios fabris convertidos: mais de 50.", "Linha de MTR: Kwun Tong Line.", "Maior centro comercial: apm (35.000 metros quadrados)."],
      fr: ["Superficie du district : environ 10 kilomètres carrés.", "Population : plus de 600 000 habitants.", "Longueur de la promenade de Kwun Tong : 1,5 kilomètre.", "Nombre d'anciennes usines reconverties : plus de 50.", "Ligne MTR : Kwun Tong Line.", "Plus grand centre commercial : apm (35 000 mètres carrés)."],
