    imageHint: "Sheung Wan traditional dried seafood shops",
    descriptionAdvanced: {
      de: "Sheung Wan ist eines der faszinierendsten Viertel von Hongkong, in dem das historische Erbe nahtlos in die moderne Finanzwelt übergeht. Bekannt als das Zentrum des traditionellen chinesischen Handels, beheimatet der Distrikt die berühmte 'Dried Seafood Street' (Des Voeux Road West), wo Geschäfte seit Generationen mit getrockneten Abalonen, Jakobsmuscheln und exotischen Heilkräutern handeln. Hier mischt sich der intensive Geruch traditioneller Waren mit der geschäftigen Atmosphäre der nahegelegenen Bürokomplexe von Central. Ein architektonisches Highlight ist der Western Market, ein im edwardianischen Stil erbautes Backsteingebäude, das heute Kunsthandwerksläden beherbergt. Sheung Wan ist auch für seine spirituelle Bedeutung bekannt, insbesondere durch den Man-Mo-Tempel, einen der ältesten und bedeutendsten Tempel der Stadt, der dem Gott der Literatur und dem Gott des Krieges gewidmet ist. Während die steilen Gassen und Treppenwege an das alte Hongkong erinnern, haben sich in den letzten Jahren zahlreiche moderne Galerien und Cafés etabliert, die das Viertel zu einem kulturellen Hotspot machen.",
      hu: "Sheung Wan Hongkong egyik legrégebbi negyede, ahol a hagyományos kínai életmód és a modern üzleti világ különleges elegyet alkot. A terület a hagyományos kínai orvoslás és a szárított tengeri termékek kereskedelmének központja; a Wing Lok utca és a Des Voeux Road West környékén százával sorakoznak az üzletek, ahol egzotikus gyógynövényeket, szárított abalont és gombákat kínálnak. Ez a negyed ad otthont a híres Man Mo-templomnak is, amely 1847-ben épült az irodalom és a háború isteneinek tiszteletére, és máig a helyi közösség spirituális központja. Az építészeti örökségek közül kiemelkedik a Western Market edwardi stílusú vörös téglaépülete, amely egykor piacnak adott otthont. Sheung Wan domboldalra kúszó szűk utcái és meredek lépcsősorai kontrasztot alkotnak a szomszédos Central negyed felhőkarcolóival. Az utóbbi években a környék művészeti negyeddé is vált, ahol modern galériák, dizájnerboltok és hangulatos kávézók várják a látogatókat a történelmi falak között.",
      ro: "Sheung Wan este un district emblematic din Hong Kong, reprezentând punctul de întâlnire între tradițiile comerciale chinezești și dinamismul economic modern. Zona este celebră pentru străzile sale specializate, precum Wing Lok Street, unde se desfășoară cel mai mare comerț angro de fructe de mare uscate și ierburi medicinale tradiționale din regiune. Aici, mirosul specific de ginseng și pește uscat umple aerul, oferind o experiență senzorială autentică, la doar câțiva pași de zgârie-norii din sticlă ai sectorului financiar. Un reper istoric major este Templul Man Mo, dedicat zeilor literaturii și războiului, unde spiralele de tămâie suspendate creează o atmosferă mistică. Arhitectura colonială este reprezentată de Western Market, o clădire din cărămidă roșie construită în stil edwardian, care a fost restaurată și transformată într-un centru comercial pentru artizanat. Districtul a evoluat recent într-un hub creativ, străzile sale în pantă fiind acum pline de galerii de artă contemporană, cafenele hip și buticuri de design, păstrând în același timp farmecul vechiului Hong Kong.",
      en: "Sheung Wan is a captivating district on Hong Kong Island where the city's colonial past and traditional Chinese customs converge with contemporary lifestyle. As a cornerstone of the city's trade history, it is world-renowned for its specialized markets, particularly the 'Dried Seafood Street' along Des Voeux Road West, where wholesalers trade in premium abalone, scallops, and traditional medicinal herbs. The area serves as a vital hub for Traditional Chinese Medicine (TCM), with narrow lanes filled with historic shops that have remained unchanged for decades. Key cultural landmarks include the Man Mo Temple, one of the city's oldest and most revered Taoist sites, and the Western Market, a striking Edwardian-style red-brick building. Despite its proximity to the gleaming financial towers of Central, Sheung Wan retains a gritty, authentic charm with its steep staircase streets and hidden alleyways. In recent years, it has transformed into a trendy arts hub, featuring numerous independent galleries, boutique shops, and artisanal cafes that breathe new life into its historic urban fabric.",
      es: "Sheung Wan es un distrito comercial histórico en la isla de Hong Kong, al oeste de Central. Antaño fue el centro del comercio tradicional chino de hierbas, mariscos secos y seda. Hoy, Sheung Wan es un barrio dinámico con una mezcla de tiendas antiguas y oficinas modernas. Las calles están llenas de tiendas de antigüedades, casas de té y galerías. Sheung Wan también alberga la Terminal de Ferry de Macao y la estación de MTR Sheung Wan. El distrito es conocido por sus mercados y su escena culinaria. A pesar de la modernización, Sheung Wan conserva gran parte de su encanto histórico. Es un nodo importante para el comercio con China continental y Macao.",
      pt: "Sheung Wan é um distrito comercial histórico na ilha de Hong Kong, a oeste de Central. Foi outrora o centro do comércio tradicional chinês de ervas, marisco seco e seda. Hoje, Sheung Wan é um bairro dinâmico com uma mistura de lojas antigas e escritórios modernos. As ruas estão repletas de lojas de antiguidades, casas de chá e galerias. Sheung Wan também alberga o Terminal de Ferries de Macau e a estação de MTR Sheung Wan. O distrito é conhecido pelos seus mercados e pela cena gastronómica. Apesar da modernização, Sheung Wan preservou muito do seu encanto histórico. É um nó importante para o comércio com a China continental e Macau.",
      fr: "Sheung Wan est un quartier commerçant historique de l'île de Hong Kong, situé à l'ouest de Central. C'était autrefois le centre du commerce traditionnel chinois d'herbes médicinales, de fruits de mer séchés et de soie. Aujourd'hui, Sheung Wan est un quartier dynamique mêlant boutiques anciennes et bureaux modernes. Les rues regorgent d'antiquaires, de maisons de thé et de galeries. Sheung Wan abrite également le terminal de ferry de Macao et la station de MTR Sheung Wan. Le quartier est célèbre pour ses marchés et sa scène culinaire. Malgré la modernisation, Sheung Wan a conservé une grande partie de son charme historique. C'est une plaque tournante majeure pour les échanges avec la Chine continentale et Macao.",
    },
