      hu: ["Kapacitás: 3737 MW.", "Üzemeltető: Hongkong Electric.", "Megnyitás éve: 1982.", "LNG átállás: 2022.", "Hatásfok: >40%.", "A sziget áramellátásának 80%-át biztosítja."],
