      en: ["Capacity: 2,500 MW.", "Operator: CLP Power.", "Commissioned: 1996.", "CO2 reduction: 8 million tonnes per year.", "Supplies over 1 million households.", "Thermal efficiency: approximately 58%."],
      es: ["Potencia instalada: 2.500 MW.", "Operador: CLP Power.", "Puesta en marcha: 1996.", "Reducción de CO₂: 8 millones de toneladas al año.", "Suministra a más de 1 millón de hogares.", "Eficiencia: aproximadamente 58%."],
