      pt: ["Antigo Bond Centre", "Projetado por Paul Rudolph", "Símbolo do crescimento económico", "Centro de serviços jurídicos"],
      fr: ["Anciennement Bond Centre", "Conçu par Paul Rudolph", "Symbole de la croissance économique", "Centre de services juridiques"],
